mapper.select:
SELECT 


GROUP BY cps.id
ORDER BY

    ${filter.orderBy}
    MAX(cpss.ordering) DESC


    LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.update:
UPDATE crm_support_pipeline_settings
SET is_active = 2,
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id}
AND is_active = 1

mapper.delete:
DELETE FROM crm_support_stag_activities
WHERE crm_support_pipeline_setting_id = #{pipelineId}
AND crm_support_stag_id = #{stageId}
